'use server'

import { revalidatePath } from 'next/cache'
import { cookies } from 'next/headers'

const NOTIFICATIONS_COOKIE = 'notifications_enabled'

export async function toggleNotificationPreference() {
  const cookieStore = await cookies()
  const isOn = cookieStore.get(NOTIFICATIONS_COOKIE)?.value !== 'false'
  cookieStore.set(NOTIFICATIONS_COOKIE, isOn ? 'false' : 'true', {
    httpOnly: true,
    sameSite: 'lax',
    path: '/',
    maxAge: 60 * 60 * 24 * 365,
    secure: process.env.NODE_ENV === 'production',
  })

  revalidatePath('/')
}

