import { cookies } from 'next/headers'
import { toggleNotificationPreference } from '@/app/actions/notifications'

const NOTIFICATIONS_COOKIE = 'notifications_enabled'

export default async function Home() {
  const cookieStore = await cookies()
  const notificationsOn =
    cookieStore.get(NOTIFICATIONS_COOKIE)?.value !== 'false'

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently{' '}
        <strong>{notificationsOn ? 'on' : 'off'}</strong>.
      </p>
      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn notifications {notificationsOn ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

